function validate(input) {
  const [{ EmployeeShifts = [] }] = input;
  const keys = new Set(), time = /^\d{4}-\d{2}-\d{2} \d{2}:\d{2}:00$/;
  for (const [id, start, end] of EmployeeShifts) {
    if (id === null || start === null || end === null) return 'EmployeeShifts rows may not contain null.';
    if (!time.test(start) || !time.test(end)) return `Times must look like 2023-10-01 09:00:00 (whole minutes).`;
    if (end <= start) return `A shift of employee ${id} must end after ${start}.`;
    const key = `${id}|${start}`;
    if (keys.has(key)) return `Employee ${id} has two shifts starting at ${start}.`;
    keys.add(key);
  }
  return null;
}

