function generate(rand, size) {
  const pick = (n) => Math.floor(rand() * n);
  const two = (n) => String(n).padStart(2, '0');
  const stamp = (minutes) => {
    const d = new Date(Date.UTC(2023, 9, 1) + minutes * 60000);
    return `${d.getUTCFullYear()}-${two(d.getUTCMonth() + 1)}-${two(d.getUTCDate())} ${two(d.getUTCHours())}:${two(d.getUTCMinutes())}:00`;
  };
  const small = size === 'small';
  const employees = small ? (pick(8) === 0 ? 0 : 1 + pick(3)) : 250;
  const rows = [];
  for (let e = 1; e <= employees; e++) {
    const id = small ? e * 2 + pick(2) : e;
    const shifts = small ? 1 + pick(4) : 8;
    const starts = new Set();
    for (let k = 0; k < shifts && rows.length < (small ? 8 : 2000); k++) {
      // Small cases start on whole hours from 18:00 to 05:00 the next day, so overlaps, nesting, touching ends
      // and shifts that cross midnight or start on the following date are all common.
      const start = small ? 1080 + 60 * pick(12) : 360 + 30 * pick(144);
      if (starts.has(start)) continue;
      starts.add(start);
      const length = small ? 60 * (1 + pick(8)) : 30 * (2 + pick(18));
      rows.push([id, stamp(start), stamp(start + length)]);
    }
  }
  for (let i = rows.length - 1; i > 0; i--) { const j = pick(i + 1); [rows[i], rows[j]] = [rows[j], rows[i]]; }
  return [{ EmployeeShifts: rows }];
}
